input.sparql:
SELECT ?s ?class ?tsid WHERE {
  ?s a brick:ElectricPowerMeter .
  ?s brick:hasLocation ?loc .
  ?loc a brick:Building .
  ?s ref:hasTimeseriesId ?tsid .
}

SELECT ?s ?class ?tsid WHERE {
  ?s ref:hasTimeseriesId ?tsid .
  ?s a ?class .
  FILTER (LCASE(STR(?class)) LIKE "%electric%" || LCASE(STR(?class)) LIKE "%energy%" || LCASE(STR(?class)) LIKE "%power%")
}

SELECT ?s ?class ?tsid WHERE {
  ?s ref:hasTimeseriesId ?tsid .
  ?s a ?class .
  {
    FILTER (LCASE(STR(?class)) LIKE "%electric%")
  } UNION {
    FILTER (LCASE(STR(?class)) LIKE "%energy%")
  } UNION {
    FILTER (LCASE(STR(?class)) LIKE "%power%")
  }
}

SELECT ?class (COUNT(?s) as ?c) WHERE {
  ?s ref:hasTimeseriesId ?tsid .
  ?s a ?class .
} GROUP BY ?class

SELECT ?p ?class WHERE {
  ?p ref:hasTimeseriesId ?tsid .
  ?p a ?class .
  ?p brick:hasLocation ?loc .
  ?loc brick:hasName ?name .
} LIMIT 30

